import{_ as e,o as a,c as d,a2 as l}from"./chunks/framework.CC9cRD7J.js";const g=JSON.parse('{"title":"Tabla de Permisos","description":"","frontmatter":{},"headers":[],"relativePath":"referencia/permisos.md","filePath":"referencia/permisos.md","lastUpdated":1793573363000}'),r={name:"referencia/permisos.md"};function o(s,t,i,n,c,f){return a(),d("div",null,[...t[0]||(t[0]=[l('<h1 id="tabla-de-permisos" tabindex="-1">Tabla de Permisos <a class="header-anchor" href="#tabla-de-permisos" aria-label="Permalink to &quot;Tabla de Permisos&quot;">​</a></h1><p>A continuación se presenta la lista completa de nodos de permisos para configurar en gestores como <strong>LuckPerms</strong>:</p><h2 id="👑-permiso-comodin-wildcard" tabindex="-1">👑 Permiso Comodín (Wildcard) <a class="header-anchor" href="#👑-permiso-comodin-wildcard" aria-label="Permalink to &quot;👑 Permiso Comodín (Wildcard)&quot;">​</a></h2><ul><li><code>staff.*</code>: Otorga acceso a prácticamente todas las funciones y comandos de moderación de StaffPlus (excepto las restricciones de bloqueo de comandos).</li></ul><hr><h2 id="🛡️-permisos-de-modo-staff-y-gadgets" tabindex="-1">🛡️ Permisos de Modo Staff y Gadgets <a class="header-anchor" href="#🛡️-permisos-de-modo-staff-y-gadgets" aria-label="Permalink to &quot;🛡️ Permisos de Modo Staff y Gadgets&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Permiso</th><th style="text-align:left;">Descripción</th></tr></thead><tbody><tr><td style="text-align:left;"><code>staff.mode</code></td><td style="text-align:left;">Permite usar <code>/staff</code> para entrar y salir del Modo Staff.</td></tr><tr><td style="text-align:left;"><code>staff.compass</code></td><td style="text-align:left;">Permite usar el propulsor (brújula) en Modo Staff.</td></tr><tr><td style="text-align:left;"><code>staff.random-teleport</code></td><td style="text-align:left;">Permite usar el teleport aleatorio (ojo de ender).</td></tr><tr><td style="text-align:left;"><code>staff.gui</code></td><td style="text-align:left;">Permite abrir el GUI Hub (papel).</td></tr><tr><td style="text-align:left;"><code>staff.counter</code></td><td style="text-align:left;">Permite abrir la lista de staff conectados (cabeza de jugador).</td></tr><tr><td style="text-align:left;"><code>staff.follow</code></td><td style="text-align:left;">Permite seguir/montar a otros jugadores (rienda).</td></tr><tr><td style="text-align:left;"><code>staff.cps</code></td><td style="text-align:left;">Permite iniciar pruebas de clics por segundo (reloj).</td></tr></tbody></table><hr><h2 id="🔨-permisos-de-sanciones-y-moderacion" tabindex="-1">🔨 Permisos de Sanciones y Moderación <a class="header-anchor" href="#🔨-permisos-de-sanciones-y-moderacion" aria-label="Permalink to &quot;🔨 Permisos de Sanciones y Moderación&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Permiso</th><th style="text-align:left;">Descripción</th></tr></thead><tbody><tr><td style="text-align:left;"><code>staffplus.ban</code></td><td style="text-align:left;">Permite usar <code>/ban</code> y abrir el menú gráfico <code>/bangui</code>.</td></tr><tr><td style="text-align:left;"><code>staffplus.tempban</code></td><td style="text-align:left;">Permite usar <code>/tempban</code> para sanciones temporales.</td></tr><tr><td style="text-align:left;"><code>staffplus.banip</code></td><td style="text-align:left;">Permite usar <code>/banip</code> y <code>/tempbanip</code> para sancionar direcciones IP.</td></tr><tr><td style="text-align:left;"><code>staffplus.unban</code></td><td style="text-align:left;">Permite usar <code>/unban</code> y <code>/unbanip</code> para desbanear jugadores o IPs.</td></tr><tr><td style="text-align:left;"><code>staffplus.baninfo</code></td><td style="text-align:left;">Permite consultar la información de un ban con <code>/baninfo</code>.</td></tr><tr><td style="text-align:left;"><code>staff.freeze</code></td><td style="text-align:left;">Permite congelar jugadores con <code>/freeze</code> o la vara de blaze.</td></tr><tr><td style="text-align:left;"><code>staff.freeze.bypass</code></td><td style="text-align:left;">Inmunidad: impide que el jugador con este permiso sea congelado.</td></tr><tr><td style="text-align:left;"><code>staff.examine</code></td><td style="text-align:left;">Permite examinar el inventario de jugadores con <code>/examine</code> o el cofre.</td></tr><tr><td style="text-align:left;"><code>staff.examine.modify</code></td><td style="text-align:left;">Permite retirar o alterar objetos dentro de la interfaz de <code>/examine</code>.</td></tr><tr><td style="text-align:left;"><code>staff.warn</code></td><td style="text-align:left;">Permite emitir advertencias con <code>/warn</code> y gestionar <code>/notes</code>.</td></tr><tr><td style="text-align:left;"><code>staff.warn.bypass</code></td><td style="text-align:left;">Inmunidad: impide recibir advertencias con <code>/warn</code>.</td></tr><tr><td style="text-align:left;"><code>staff.report</code></td><td style="text-align:left;">Permite recibir alertas de reportes y gestionarlos.</td></tr><tr><td style="text-align:left;"><code>staff.report.bypass</code></td><td style="text-align:left;">Inmunidad: impide que otros usuarios puedan reportar a este jugador.</td></tr></tbody></table><hr><h2 id="💬-permisos-de-chat-y-vanish" tabindex="-1">💬 Permisos de Chat y Vanish <a class="header-anchor" href="#💬-permisos-de-chat-y-vanish" aria-label="Permalink to &quot;💬 Permisos de Chat y Vanish&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Permiso</th><th style="text-align:left;">Descripción</th></tr></thead><tbody><tr><td style="text-align:left;"><code>staff.staffchat</code></td><td style="text-align:left;">Permite leer y escribir en el chat de staff con <code>/sc</code> o el prefijo <code>@</code>.</td></tr><tr><td style="text-align:left;"><code>staff.vanish.total</code></td><td style="text-align:left;">Permite usar <code>/vanish total</code> para invisibilidad completa.</td></tr><tr><td style="text-align:left;"><code>staff.vanish.list</code></td><td style="text-align:left;">Permite usar <code>/vanish list</code> para ocultarse del tablist.</td></tr><tr><td style="text-align:left;"><code>staff.chat.clear</code></td><td style="text-align:left;">Permite limpiar el chat global con <code>/chat clear</code>.</td></tr><tr><td style="text-align:left;"><code>staff.chat.toggle</code></td><td style="text-align:left;">Permite silenciar o habilitar el chat con <code>/chat toggle</code>.</td></tr><tr><td style="text-align:left;"><code>staff.chat.slow</code></td><td style="text-align:left;">Permite ralentizar la velocidad del chat con <code>/chat slow</code>.</td></tr><tr><td style="text-align:left;"><code>staff.blacklist</code></td><td style="text-align:left;">Permite evadir el filtro de palabras prohibidas y enlaces.</td></tr><tr><td style="text-align:left;"><code>staff.tickets</code></td><td style="text-align:left;">Permite recibir y contestar tickets de ayuda con <code>/ticket</code>.</td></tr></tbody></table><hr><h2 id="🚨-permisos-de-alertas-y-administracion" tabindex="-1">🚨 Permisos de Alertas y Administración <a class="header-anchor" href="#🚨-permisos-de-alertas-y-administracion" aria-label="Permalink to &quot;🚨 Permisos de Alertas y Administración&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Permiso</th><th style="text-align:left;">Descripción</th></tr></thead><tbody><tr><td style="text-align:left;"><code>staff.alerts.xray</code></td><td style="text-align:left;">Permite recibir avisos cuando alguien pica minerales valiosos.</td></tr><tr><td style="text-align:left;"><code>staff.alerts.mention</code></td><td style="text-align:left;">Permite recibir avisos acústicos cuando mencionan tu nombre en el chat.</td></tr><tr><td style="text-align:left;"><code>staff.alerts.namechange</code></td><td style="text-align:left;">Permite recibir avisos cuando un jugador entra con un nick cambiado.</td></tr><tr><td style="text-align:left;"><code>staff.revive</code></td><td style="text-align:left;">Permite devolver el inventario a un jugador muerto con <code>/revive</code>.</td></tr><tr><td style="text-align:left;"><code>staff.strip</code></td><td style="text-align:left;">Permite quitarle la armadura a un jugador con <code>/strip</code>.</td></tr><tr><td style="text-align:left;"><code>staff.member</code></td><td style="text-align:left;">Identifica al usuario como miembro formal del staff (para login y listas).</td></tr><tr><td style="text-align:left;"><code>staff.staffplus</code></td><td style="text-align:left;">Permite recargar la configuración con <code>/staffplus reload</code>.</td></tr><tr><td style="text-align:left;"><code>staff.staffplus.resetpassword</code></td><td style="text-align:left;">Permite restablecer contraseñas de otros miembros del staff.</td></tr><tr><td style="text-align:left;"><code>staff.staffplus.hideip</code></td><td style="text-align:left;">Muestra la IP en <code>/examine</code> y protege contra inspecciones no autorizadas.</td></tr><tr><td style="text-align:left;"><code>staff.staffplus.clearinv</code></td><td style="text-align:left;">Permite limpiar inventarios con <code>/clear &lt;jugador&gt;</code>.</td></tr></tbody></table>',16)])])}const y=e(r,[["render",o]]);export{g as __pageData,y as default};
